<?php if(Auth::can('enquiries')):?><section class="panel"><div class="panel-heading"><div><h2>Recent enquiries</h2><p>The next conversation starts here.</p></div><a class="text-link" href="<?=e(cms_url('/admin/enquiries'))?>">View all →</a></div><?php if($recent):?><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Requirement</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($recent as $item):?><tr><td><strong><?=e($item['name'])?></strong><small><?=e($item['email'])?></small></td><td><?=e($item['requirement'])?></td><td><span class="status <?=$item['status']?>"><?=e(ucfirst($item['status']))?></span></td><td><?=e($item['created_at'])?></td><td><a class="text-link" href="<?=e(cms_url('/admin/enquiries/'.$item['id']))?>">Open →</a></td></tr><?php endforeach?></tbody></table></div><?php else:?><div class="empty-state small"><span>✉</span><h3>All caught up</h3><p>Enquiries submitted through your website will appear here.</p></div><?php endif?></section><?php endif?>
